{
  "description": "Run the Git identity guard before Bash tool calls.",
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "^Bash$",
        "hooks": [
          {
            "type": "command",
            "command": "/usr/bin/python3 /home/mark/.claude/hooks/git-identity-guard.py",
            "timeout": 45,
            "statusMessage": "Checking Git/GitHub identity"
          }
        ]
      }
    ]
  }
}
